"""TG 绿点（可见在线）：挂在 dispatch Telethon 上，不另开 session。

逻辑（2026-09-28）：
- 以上班打卡为起点、下班打卡为终点（读 OneHR schedule_state），不按固定钟点
- 打卡窗口内间歇绿点，不要持续在线
- 单次离线不超过 TG_VISIBLE_ONLINE_MAX_OFFLINE_SEC（默认 15 分钟）
- TCP 不断开；仅 UpdateStatus 切换可见状态
"""
from __future__ import annotations

import asyncio
import json
import logging
import random
from datetime import datetime
from pathlib import Path
from zoneinfo import ZoneInfo

from config import (
    TG_VISIBLE_ONLINE_ENABLED,
    TG_VISIBLE_ONLINE_MAX_OFFLINE_SEC,
    TG_VISIBLE_ONLINE_OFFLINE_MIN_SEC,
    TG_VISIBLE_ONLINE_ONLINE_MAX_SEC,
    TG_VISIBLE_ONLINE_ONLINE_MIN_SEC,
    TG_VISIBLE_ONLINE_STATE_FILE,
    TG_WORK_ONLINE_TZ,
)

log = logging.getLogger(__name__)

_TZ = ZoneInfo(TG_WORK_ONLINE_TZ or "Asia/Shanghai")
_DEFAULT_STATE = Path.home() / ".dc-platform" / "onehr" / "schedule_state.json"


def _state_path() -> Path:
    raw = (TG_VISIBLE_ONLINE_STATE_FILE or "").strip()
    return Path(raw).expanduser() if raw else _DEFAULT_STATE


def _today() -> str:
    return datetime.now(_TZ).date().isoformat()


def _load_schedule_state() -> dict:
    path = _state_path()
    if not path.is_file():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except (OSError, json.JSONDecodeError) as exc:
        log.warning("[visible-online] read state failed %s: %s", path, exc)
        return {}


def punch_window_active(now: datetime | None = None) -> bool:
    """今日已上班打卡且尚未下班打卡 → 允许间歇绿点。"""
    t = now or datetime.now(_TZ)
    if t.tzinfo is None:
        t = t.replace(tzinfo=_TZ)
    else:
        t = t.astimezone(_TZ)
    day = t.date().isoformat()
    st = _load_schedule_state()
    checked_in = st.get("checkin") == day or st.get(f"_manual_checkin_{day}") is True
    checked_out = st.get("checkout") == day
    return bool(checked_in and not checked_out)


def should_appear_online(now: datetime | None = None) -> bool:
    """对外口径：当前是否处于「可绿」窗口（间歇循环另算）。"""
    return punch_window_active(now)


def _clamp_offline_sec(sec: int) -> int:
    mx = max(60, int(TG_VISIBLE_ONLINE_MAX_OFFLINE_SEC or 900))
    mn = max(30, int(TG_VISIBLE_ONLINE_OFFLINE_MIN_SEC or 90))
    if mn > mx:
        mn = mx
    return max(mn, min(mx, sec))


def _pick_online_sec() -> int:
    lo = max(60, int(TG_VISIBLE_ONLINE_ONLINE_MIN_SEC or 180))
    hi = max(lo, int(TG_VISIBLE_ONLINE_ONLINE_MAX_SEC or 720))
    return random.randint(lo, hi)


def _pick_offline_sec() -> int:
    mx = max(60, int(TG_VISIBLE_ONLINE_MAX_OFFLINE_SEC or 900))
    mn = max(30, int(TG_VISIBLE_ONLINE_OFFLINE_MIN_SEC or 90))
    if mn > mx:
        mn = mx
    return random.randint(mn, mx)


async def apply_visible_online(client, online: bool, *, reason: str = "") -> None:
    """仅改可见绿点；不断 TCP。online=True → offline=False。"""
    try:
        from telethon.tl.functions.account import UpdateStatusRequest
    except ImportError:
        log.error("[visible-online] telethon UpdateStatusRequest 不可用")
        return
    try:
        await client(UpdateStatusRequest(offline=not online))
        log.info(
            "[visible-online] status online=%s%s",
            online,
            f" ({reason})" if reason else "",
        )
    except Exception as exc:
        log.warning("[visible-online] UpdateStatus failed: %s", exc)


async def visible_online_loop(client) -> None:
    """打卡后间歇绿点；下班打卡后灭。"""
    if not TG_VISIBLE_ONLINE_ENABLED:
        log.info("[visible-online] disabled")
        return
    log.info(
        "[visible-online] started gate=onehr-punch state=%s "
        "online=%s-%ss offline=%s-%ss (max_offline=%ss)",
        _state_path(),
        TG_VISIBLE_ONLINE_ONLINE_MIN_SEC,
        TG_VISIBLE_ONLINE_ONLINE_MAX_SEC,
        TG_VISIBLE_ONLINE_OFFLINE_MIN_SEC,
        TG_VISIBLE_ONLINE_MAX_OFFLINE_SEC,
        TG_VISIBLE_ONLINE_MAX_OFFLINE_SEC,
    )
    want = punch_window_active()
    await apply_visible_online(
        client,
        want,
        reason="startup " + ("in-punch-window" if want else "awaiting-checkin-or-checked-out"),
    )
    while True:
        try:
            if not client.is_connected():
                await asyncio.sleep(15)
                continue
            if not punch_window_active():
                await apply_visible_online(
                    client, False, reason="outside punch window (no checkin / after checkout)"
                )
                # 等上班打卡或跨日：30s 轮询 state
                await asyncio.sleep(30)
                continue
            on_sec = _pick_online_sec()
            await apply_visible_online(client, True, reason=f"burst {on_sec}s")
            await _sleep_interruptible(on_sec)
            if not punch_window_active():
                continue
            off_sec = _clamp_offline_sec(_pick_offline_sec())
            await apply_visible_online(client, False, reason=f"pause {off_sec}s")
            await _sleep_interruptible(off_sec)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log.exception("[visible-online] loop error: %s", exc)
            await asyncio.sleep(30)


async def _sleep_interruptible(total_sec: int) -> None:
    """分段睡，下班打卡后尽快醒并灭绿点。"""
    left = max(0, int(total_sec))
    while left > 0:
        chunk = min(20, left)
        await asyncio.sleep(chunk)
        left -= chunk
        if not punch_window_active():
            return

